    @Test("fingering")
    func fingering() async throws {
        let score: Score = try await MusicXmlImporterTestHelper.loadFile("test-data/musicxml4/fingering.xml")
        let notes: (Double, Double) -> List<Note> = { (track: Double, firstBar: Double) -> List<Note> in
            let result: List<Note> = List<Note>()
            do {
                var i: Double = firstBar
                while i < firstBar + 6.0 {
                    for b in score.tracks[(track).toInt()].staves[0].bars[(i).toInt()].voices[0].beats {
                        result.push(b.notes[0])
                    }
                    i += 1
                }
            }
            return result
        }
        let letters: List<Fingers> = List<Fingers>(Fingers.Thumb, Fingers.Thumb, Fingers.Thumb, Fingers.Thumb, Fingers.IndexFinger, Fingers.IndexFinger, Fingers.MiddleFinger, Fingers.MiddleFinger, Fingers.AnnularFinger, Fingers.AnnularFinger, Fingers.LittleFinger, Fingers.LittleFinger, Fingers.LittleFinger, Fingers.LittleFinger, Fingers.LittleFinger, Fingers.LittleFinger, Fingers.LittleFinger, Fingers.Unknown)
        let keyboardDigits: List<Fingers> = List<Fingers>(Fingers.NoOrDead, Fingers.Thumb, Fingers.IndexFinger, Fingers.MiddleFinger, Fingers.AnnularFinger, Fingers.LittleFinger)
        let fretDigits: List<Fingers> = List<Fingers>(Fingers.NoOrDead, Fingers.IndexFinger, Fingers.MiddleFinger, Fingers.AnnularFinger, Fingers.LittleFinger, Fingers.Thumb)
        func expectFingers(_ actual: List<Fingers>, _ digits: List<Fingers>) {
            let expected: List<Fingers> = List<Fingers>()
            for f in digits {
                expected.push(f)
            }
            for f in letters {
                expected.push(f)
            }
            TestGlobals.expect(actual).toEqual(expected)
        }
        try TestGlobals.expect(score.tracks.jsElement(0).playbackInfo.program).toBe(24.0)
        expectFingers(notes(0.0, 0.0).map({ (n: Note) -> Fingers in
            return n.leftHandFinger
        }), fretDigits)
        expectFingers(notes(0.0, 6.0).map({ (n: Note) -> Fingers in
            return n.rightHandFinger
        }), keyboardDigits)
        try TestGlobals.expect(score.tracks.jsElement(1).playbackInfo.program).toBe(0.0)
        expectFingers(notes(1.0, 0.0).map({ (n: Note) -> Fingers in
            return n.leftHandFinger
        }), keyboardDigits)
        expectFingers(notes(1.0, 6.0).map({ (n: Note) -> Fingers in
            return n.rightHandFinger
        }), keyboardDigits)
    }

