            return "<measure number=\"\((n).toTemplate())\">\((TypeHelper.isTruthy(attributes) ? "<attributes><divisions>1</divisions>\((attributes).toTemplate())</attributes>" : "").toTemplate())\((notes).toTemplate())</measure>"
        }
        let xml: String = """
<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<score-partwise version=\"4.0\">\n  <part-list><score-part id=\"P1\"><part-name>GP8</part-name></score-part><score-part id=\"P2\"><part-name>Guitar</part-name></score-part></part-list>\n  <part id=\"P1\">\((measure(1.0, "<staves>2</staves><clef number=\"1\"><sign>G</sign><line>2</line></clef>\((tabStaff(" number=\"2\"")).toTemplate())" + "<transpose number=\"1\"><diatonic>0</diatonic><chromatic>0</chromatic><octave-change>-1</octave-change></transpose>", [note("", "C", 5.0, "<staff>1</staff>", harmonic("artificial", "<base-pitch/>")), chord("G", 5.0, "artificial", "<touching-pitch/>"), chord("G", 6.0, "artificial", "<sounding-pitch/>"), "<backup><duration>4</duration></backup>", note("", "C", 4.0, "<staff>2</staff>", harmonic("artificial", "<base-pitch/>") + tab(2.0, 1.0)), chord("G", 5.0, "artificial", "<touching-pitch/>"), chord("G", 6.0, "artificial", "<sounding-pitch/>")].joined())).toTemplate())</part>\n  <part id=\"P2\">\((List<String>(note("", "G", 4.0, "", "<harmonic/>\((tab(3.0, 12.0)).toTemplate())"), note("", "G", 4.0, "", harmonic("natural", "") + tab(3.0, 12.0)), note("", "C", 4.0, "", harmonic("natural", "<base-pitch/>") + tab(2.0, 1.0)), note("", "D", 4.0, "", harmonic("natural", "<touching-pitch/>") + tab(3.0, 7.0)), note("", "C", 4.0, "", harmonic("artificial", "") + tab(2.0, 1.0)), note("", "C", 4.0, "", harmonic("artificial", "<base-pitch/>") + tab(2.0, 1.0)) + chord("F", 4.0, "artificial", "<touching-pitch/>"), note("", "C", 4.0, "", harmonic("artificial", "<base-pitch/>") + tab(2.0, 1.0)) + chord("G", 5.0, "artificial", "<sounding-pitch/>"), note("", "G", 3.0, "", harmonic("natural", "<base-pitch/>") + tab(3.0, 0.0)) + chord("D", 4.0, "natural", "<touching-pitch/>") + chord("D", 5.0, "natural", "<sounding-pitch/>"), note("", "C", 4.0, "", harmonic("artificial", "<base-pitch/>") + tab(2.0, 1.0)) + chord("C", 5.0, "artificial", "<touching-pitch/>") + note("<chord/>", "E", 4.0, "", tab(1.0, 0.0)) + note("<chord/>", "A", 3.0, "", harmonic("artificial", "<base-pitch/>") + tab(3.0, 2.0)) + chord("E", 4.0, "artificial", "<touching-pitch/>")).map({ (content: String, i: Double) -> String in
            return measure(i + 1.0, i == 0.0 ? tabStaff("") : "", content)
        }).join("")).toTemplate())</part>\n</score-partwise>
