    @Suite("spans")
    final class SpansSuite {
        nonisolated(unsafe) private static let tuning: List<String> = List<String>("E2", "A2", "D3", "G3", "B3", "E4")

        private static func load(_ parts: List<List<String>>, _ staves: Double = 1.0, _ divisions: Double = 1.0, _ software: String = "") throws -> Score {
            var attributes: String = "<attributes><divisions>\((divisions).toTemplate())</divisions><time><beats>4</beats><beat-type>4</beat-type></time>"
            if staves == 1.0 {
                attributes += "<clef><sign>TAB</sign><line>5</line></clef><staff-details><staff-lines>6</staff-lines>"
                do {
                    var i: Double = 0.0
                    while i < SpansSuite.tuning.length {
                        attributes += "<staff-tuning line=\"\((i + 1.0).toTemplate())\"><tuning-step>\((SpansSuite.tuning[(i).toInt()][0]).toTemplate())</tuning-step><tuning-octave>\((SpansSuite.tuning[(i).toInt()][1]).toTemplate())</tuning-octave></staff-tuning>"
                        i += 1
                    }
                }
                attributes += "</staff-details>"
            } else {
                attributes += "<staves>\((staves).toTemplate())</staves><clef number=\"1\"><sign>G</sign><line>2</line></clef><clef number=\"2\"><sign>F</sign><line>4</line></clef>"
            }
            attributes += "</attributes>"
            var xml: String = "<?xml version=\"1.0\" encoding=\"UTF-8\"?><score-partwise version=\"4.0\">"
            if software.length > 0 {
                xml += "<identification><encoding><software>\((software).toTemplate())</software></encoding></identification>"
            }
            xml += "<part-list>"
            do {
                var i: Double = 0.0
                while i < parts.length {
                    xml += "<score-part id=\"P\((i + 1.0).toTemplate())\"><part-name>P\((i + 1.0).toTemplate())</part-name></score-part>"
                    i += 1
                }
            }
            xml += "</part-list>"
            do {
                var i: Double = 0.0
                while i < parts.length {
                    xml += "<part id=\"P\((i + 1.0).toTemplate())\">"
                    do {
                        var j: Double = 0.0
                        while try j < parts.jsElement((i).toInt()).length {
                            xml += "<measure number=\"\((j + 1.0).toTemplate())\">\((j == 0.0 ? attributes : "").toTemplate())\((parts[(i).toInt()][(j).toInt()]).toTemplate())</measure>"
                            j += 1
                        }
                    }
                    xml += "</part>"
                    i += 1
                }
            }
            xml += "</score-partwise>"
            return try MusicXmlImporterTestHelper.prepareImporterWithBytes(IOHelper.stringToBytes(xml)).readScore()
        }

        private static func tab(_ pitch: String, _ stringNumber: Double, _ fret: Double = 0.0, _ notations: String = "") -> String {
            return ("<note><pitch><step>\((pitch[0]).toTemplate())</step><octave>\((pitch[1]).toTemplate())</octave></pitch>" + "<duration>1</duration><voice>1</voice><type>quarter</type>" + "<notations><technical><string>\((stringNumber).toTemplate())</string><fret>\((fret).toTemplate())</fret></technical>\((notations).toTemplate())</notations></note>")
        }

        private static func note(_ pitch: String, _ voice: Double = 1.0, _ staff: Double = 0.0, _ notations: String = "", _ duration: Double = 1.0, _ type: String = "quarter") -> String {
            return ("<note><pitch><step>\((pitch[0]).toTemplate())</step><octave>\((pitch[1]).toTemplate())</octave></pitch>" + "<duration>\((duration).toTemplate())</duration><voice>\((voice).toTemplate())</voice><type>\((type).toTemplate())</type>" + "\((staff > 0 ? "<staff>\((staff).toTemplate())</staff>" : "").toTemplate())\((notations.length > 0 ? "<notations>\((notations).toTemplate())</notations>" : "").toTemplate())</note>")
        }

        private static func chordNote(_ pitch: String, _ stringNumber: Double, _ fret: Double, _ notations: String = "") -> String {
            return SpansSuite.tab(pitch, stringNumber, fret, notations).replace("<note>", "<note><chord/>")
        }

        private static func openStrings(_ count: Double) -> String {
            var notes: String = ""
            do {
                var i: Double = 0.0
                while i < count {
                    notes += SpansSuite.tab("E2", 6.0)
                    i += 1
                }
            }
            return notes
        }

        private static func quarters(_ count: Double, _ pitch: String = "C4", _ voice: Double = 1.0, _ staff: Double = 0.0) -> String {
            var notes: String = ""
            do {
                var i: Double = 0.0
                while i < count {
                    notes += SpansSuite.note(pitch, voice, staff)
                    i += 1
                }
            }
            return notes
        }

        private static func direction(_ directionTypes: String, _ extra: String = "") -> String {
            return "<direction>\((directionTypes).toTemplate())\((extra).toTemplate())</direction>"
        }

        private static func dashes(_ words: String, _ type: String, _ number: String = "1", _ extra: String = "") -> String {
            let label: String = words.length > 0 ? "<direction-type><words>\((words).toTemplate())</words></direction-type>" : ""
            return SpansSuite.direction("\((label).toTemplate())<direction-type><dashes type=\"\((type).toTemplate())\" number=\"\((number).toTemplate())\"/></direction-type>", extra)
        }

        private static func notesOf(_ score: Score, _ bar: Double = 0.0, _ staff: Double = 0.0, _ voice: Double = 0.0, _ track: Double = 0.0) -> List<Note> {
            let notes: List<Note> = List<Note>()
            for b in score.tracks[(track).toInt()].staves[(staff).toInt()].bars[(bar).toInt()].voices[(voice).toInt()].beats {
                for n in b.notes {
                    notes.push(n)
                }
            }
            return notes
        }

        private static func beatsOf(_ score: Score, _ bar: Double = 0.0, _ staff: Double = 0.0, _ voice: Double = 0.0, _ track: Double = 0.0) -> List<Beat> {
            return score.tracks[(track).toInt()].staves[(staff).toInt()].bars[(bar).toInt()].voices[(voice).toInt()].beats
        }

        private static func noteLengths(_ score: Score) throws -> List<Double> {
            let handler: FlatMidiEventGenerator = FlatMidiEventGenerator()
            try MidiFileGenerator(score, Settings(), handler).generate()
            let lengths: List<Double> = List<Double>()
            for e in handler.midiEvents {
                if e is FlatNoteEvent {
                    lengths.push((e as! FlatNoteEvent).length)
                }
            }
            return lengths
        }

