                let score: Score = try SpansSuite.load(List<List<String>>(List<String>(MeasureStylesSuite.style("<slash type=\"start\"/>") + SpansSuite.quarters(4.0), SpansSuite.quarters(4.0)), List<String>(SpansSuite.quarters(4.0), SpansSuite.quarters(4.0))), 2.0)
                TestGlobals.expect(SpansSuite.beatsOf(score, 1.0).map({ (b: Beat) -> Bool in
                    return b.slashed
