        @Suite("note-links")
        final class NoteLinksSuite {
            @Test("ties")
            func ties() async throws {
                let score: Score = try SpansSuite.load(List<List<String>>(List<String>(SpansSuite.note("C5", 1.0, 0.0, "<tied type=\"start\"/>") + SpansSuite.note("C5") + SpansSuite.note("C5", 1.0, 0.0, "<tied type=\"stop\"/><tied type=\"start\"/>") + SpansSuite.note("C5", 1.0, 0.0, "<tied type=\"stop\"/>"))), 2.0)
                let notes: List<Note> = SpansSuite.notesOf(score)
                try TestGlobals.expect(notes.jsElement(1).tieOrigin).toBe(notes[0])
                try TestGlobals.expect(notes.jsElement(2).isTieDestination).toBe(false)
                try TestGlobals.expect(notes.jsElement(3).tieOrigin).toBe(notes[2])
            }

