                let notes: List<Note> = SpansSuite.notesOf(score)
                try TestGlobals.expect(notes.jsElement(2).tieOrigin).toBe(notes[0])
                try TestGlobals.expect(notes.jsElement(3).tieOrigin).toBe(notes[1])
